import sqlite3,unittest

def total_with_tax(amount,rate):
    if amount<0: raise ValueError("amount must be non-negative")
    return round(amount*(1+rate),2)
def save_invoice(db,amount):
    total=total_with_tax(amount,.17);db.execute("INSERT INTO invoice(total) VALUES(?)",(total,));db.commit();return db.execute("SELECT total FROM invoice ORDER BY rowid DESC").fetchone()[0]

class Tests(unittest.TestCase):
    def test_unit_tax(self): self.assertEqual(total_with_tax(100,.17),117.0)
    def test_integration_sqlite(self):
        db=sqlite3.connect(":memory:");db.execute("CREATE TABLE invoice(total REAL CHECK(total>=0))")
        self.assertEqual(save_invoice(db,100),117.0)
suite=unittest.defaultTestLoader.loadTestsFromTestCase(Tests)
unittest.TextTestRunner(verbosity=2).run(suite)
